import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

// ⚠️ GEMINI API KEY
const GEMINI_API_KEY = ""; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [seciliMekanId, setSeciliMekanId] = useState(null);
  const [veriYukleniyor, setVeriYukleniyor] = useState(true);

  // Özellik State'leri
  const [muzekartVar, setMuzekartVar] = useState(false);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  // 1️⃣ Backend'den Mekanları Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => {
        if (!res.ok) throw new Error("Backend yok");
        return res.json();
      })
      .then(data => {
        setMekanlar(data);
        setVeriYukleniyor(false);
      })
      .catch(err => {
        console.warn("API Hatası, lütfen Backend'i çalıştır.", err);
        setVeriYukleniyor(false);
      });
  }, []);

  // ✅ KATEGORİLERE GÖRE GRUPLAMA
  const kategoriler = {
    "Tarih": mekanlar.filter(m => m.kategori === "Tarih"),
    "Doğa": mekanlar.filter(m => m.kategori === "Doğa"),
    "Eğlence": mekanlar.filter(m => m.kategori === "Eğlence"),
    "Dalış": mekanlar.filter(m => m.kategori === "Dalış"),
    "Tekne": mekanlar.filter(m => m.kategori === "Tekne"),
    "Yemek": mekanlar.filter(m => m.kategori === "Yemek"),
  };

  const kategoriArkaPlanlari = {
    "Tarih": "https://images.unsplash.com/photo-1528164344705-475426870763?q=80&w=2070", 
    "Doğa": "https://images.unsplash.com/photo-1433838552652-f9a46b332c40?q=80&w=2070", 
    "Eğlence": "https://images.unsplash.com/photo-1566737236500-c8ac43014a67?q=80&w=2070", 
    "Dalış": "https://images.unsplash.com/photo-1544551763-46a013bb70d5?q=80&w=2070",
    "Tekne": "https://images.unsplash.com/photo-1534008897995-27a23e859048?q=80&w=2070",
    "Yemek": "https://images.unsplash.com/photo-1555396273-367ea4eb4db5?q=80&w=1974", 
  };

  const rotayiHaritadaGoster = () => {
    if (favoriler.length === 0) return alert("Listeniz boş! Hadi birkaç güzel yer seçelim.");
    const duraklar = favoriler.map(m => encodeURIComponent(m.ad)).join('/');
    window.open(`https://www.google.com/maps/dir/Current+Location/${duraklar}`, '_blank');
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    else setFavoriler([...favoriler, mekan]);
  };

  const askSmartAI = async (mekan) => {
    if (seciliMekanId === mekan.id) { setSeciliMekanId(null); return; }
    setSeciliMekanId(mekan.id);
    setLoading(true);
    setAiBilgi({ cevap: "", temp: "", durum: "" });
    try {
      const wRes = await fetch(`http://localhost:5000/api/hava-durumu?lat=${mekan.lat}&lon=${mekan.lon}`);
      const wData = await wRes.json(); 
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash" });
      const prompt = `Antalya ${mekan.ad} konumundayım. Hava ${wData.sicaklik}°C. Burası için samimi bir ipucu ver.`;
      const result = await model.generateContent(prompt);
      setAiBilgi({ cevap: result.response.text(), temp: wData.sicaklik, durum: wData.durum });
    } catch (err) {
      setAiBilgi({ cevap: "Hava durumu alınamadı!", temp: "--", durum: "?" });
    } finally { setLoading(false); }
  };

  if (veriYukleniyor) return <div style={{display:'flex', justifyContent:'center', alignItems:'center', height:'100vh', background:'#111827', color:'#38bdf8', fontSize:'20px'}}>🌘 Rotalar Yükleniyor...</div>;

  return (
    <div style={{ fontFamily: "'Poppins', sans-serif", background: '#000', color: '#e2e8f0' }}>

      <style>{`
        html { scroll-behavior: smooth; }
        .nav-link { 
            color: #cbd5e1; text-decoration: none; font-size: 13px; font-weight: 600; text-transform: uppercase; 
            padding: 8px 20px; border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 50px; 
            background: rgba(255, 255, 255, 0.05); transition: all 0.3s ease; 
        }
        .nav-link:hover { color: #fff; border-color: #f97316; background: rgba(249, 115, 22, 0.2); box-shadow: 0 0 15px rgba(249, 115, 22, 0.4); transform: translateY(-2px); }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 15px 40px; background: rgba(0, 0, 0, 0.9); backdrop-filter: blur(15px); position: sticky; top: 0; z-index: 1000; border-bottom: 1px solid rgba(255,255,255,0.1); }
        .category-section { position: relative; min-height: 100vh; padding: 60px 40px; background-attachment: fixed; background-size: cover; display: flex; flex-direction: column; justify-content: center; }
        .overlay { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0, 0, 0, 0.75); z-index: 1; }
        .section-content { position: relative; z-index: 2; }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 30px; }
        .card { background: rgba(30, 41, 59, 0.85); border-radius: 20px; overflow: hidden; border: 1px solid rgba(255, 255, 255, 0.1); transition: 0.4s; }
        .card:hover { transform: translateY(-10px); border-color: #f97316; }

        /* 🌊 GELİŞMİŞ FOOTER VE DALGA STİLLERİ */
        .advanced-footer { background: #001d3d; position: relative; padding-top: 100px; margin-top: 50px; }
        .wave-container { position: absolute; top: -100px; width: 100%; height: 100px; overflow: hidden; line-height: 0; }
        .waves { position: relative; width: 100%; height: 100%; }
        .parallax > use { animation: move-forever 25s cubic-bezier(.55,.5,.45,.5) infinite; }
        .parallax > use:nth-child(1) { animation-delay: -2s; animation-duration: 7s; }
        .parallax > use:nth-child(2) { animation-delay: -3s; animation-duration: 10s; }
        .parallax > use:nth-child(3) { animation-delay: -4s; animation-duration: 13s; }
        .parallax > use:nth-child(4) { animation-delay: -5s; animation-duration: 20s; }
        @keyframes move-forever { 0% { transform: translate3d(-90px,0,0); } 100% { transform: translate3d(85px,0,0); } }

        .footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 40px; padding: 40px; position: relative; z-index: 2; }
        .footer-stats-box { display: flex; justify-content: space-around; padding: 40px; border-top: 1px solid rgba(255,255,255,0.1); border-bottom: 1px solid rgba(255,255,255,0.1); text-align: center; }
        .stat .number { display: block; font-size: 36px; font-weight: 800; color: #f97316; text-shadow: 0 0 10px rgba(249, 115, 22, 0.2); }
        .stat .label { font-size: 13px; text-transform: uppercase; color: #38bdf8; letter-spacing: 1px; }
        .footer-bottom-bar { text-align: center; padding: 30px; font-size: 13px; opacity: 0.7; border-top: 1px solid rgba(255,255,255,0.05); }
      `}</style>

      {/* Navbar */}
      <nav className="navbar">
        <div style={{ display:'flex', alignItems:'center', gap:'10px' }}>
            <span style={{fontSize:'28px'}}>🏝️</span>
            <div>
                <div style={{ fontWeight: 800, color: '#38bdf8', fontSize: '18px' }}>ANTALYA</div>
                <div style={{ fontWeight: 400, color: '#f97316', fontSize: '11px' }}>ROTA ASİSTANI</div>
            </div>
        </div>
        <div className="nav-links">
            {Object.keys(kategoriler).map(kat => (
                <a key={kat} href={`#${kat}`} className="nav-link">{kat}</a>
            ))}
        </div>
        <div style={{ display: 'flex', gap: '20px', alignItems: 'center' }}>
            <button onClick={() => setMuzekartVar(!muzekartVar)} className="muzekart-btn" style={{background: muzekartVar ? '#4f46e5' : 'transparent'}}>
              {muzekartVar ? "💳 Müzekart Var" : "💳 Müzekart Yok"}
            </button>
            <button onClick={rotayiHaritadaGoster} className="btn-gradient">Rotayı Çiz 🚀</button>
        </div>
      </nav>

      {/* İçerik */}
      {Object.keys(kategoriler).map((katAdi) => {
          const liste = kategoriler[katAdi];
          if (liste.length === 0) return null;
          return (
            <div key={katAdi} id={katAdi} className="category-section" style={{ backgroundImage: `url(${kategoriArkaPlanlari[katAdi]})` }}>
                <div className="overlay"></div>
                <div className="section-content">
                    <h2 className="category-title">{katAdi} Rotaları</h2>
                    <div className="grid">
                        {liste.map(m => (
                            <div key={m.id} className="card">
                                <div className="img-container"><img src={m.resim} className="card-img" alt={m.ad} /></div>
                                <div style={{ padding: '20px', flex:1, display:'flex', flexDirection:'column' }}>
                                    <div style={{display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:'10px'}}>
                                        <h3 style={{margin:0}}>{m.ad}</h3>
                                        <span style={{color: (muzekartVar && m.kategori === 'Tarih') ? '#4ade80' : '#f97316', fontWeight:'bold'}}>
                                            {(muzekartVar && m.kategori === 'Tarih') ? "ÜCRETSİZ" : `${m.ucret} ₺`}
                                        </span>
                                    </div>
                                    <p style={{fontSize:'13px', color:'#94a3b8', flex:1}}>{m.aciklama}</p>
                                    <div style={{ display: 'flex', gap: '10px', marginTop:'15px' }}>
                                        <button onClick={() => askSmartAI(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background:'#334155', color:'#38bdf8', cursor:'pointer', fontWeight:'bold'}}>✨ AI İpucu</button>
                                        <button onClick={() => toggleFavori(m)} style={{flex:1, padding:'10px', borderRadius:'8px', border:'none', background: favoriler.some(f=>f.id===m.id) ? '#ef4444' : '#0f766e', color:'white', cursor:'pointer', fontWeight:'bold'}}>
                                            {favoriler.some(f=>f.id===m.id) ? "Çıkar" : "Ekle +"}
                                        </button>
                                    </div>
                                    {seciliMekanId === m.id && (
                                        <div style={{marginTop:'15px', padding:'10px', background:'rgba(0,0,0,0.3)', borderRadius:'10px', borderLeft:'3px solid #38bdf8', fontSize:'13px'}}>
                                            {loading ? "Zeka düşünüyor..." : `🌡️ ${aiBilgi.temp}°C | ${aiBilgi.cevap}`}
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
          );
      })}

      {/* 🌊 GELİŞMİŞ FOOTER (Antalya Diving Tasarımı) */}
      <footer className="advanced-footer">
        <div className="wave-container">
          <svg className="waves" viewBox="0 24 150 28" preserveAspectRatio="none" shapeRendering="auto">
            <defs><path id="gentle-wave" d="M-160 44c30 0 58-18 88-18s 58 18 88 18 58-18 88-18 58 18 88 18 v44h-352z" /></defs>
            <g className="parallax">
              <use href="#gentle-wave" x="48" y="0" fill="rgba(0, 29, 61, 0.7)" />
              <use href="#gentle-wave" x="48" y="3" fill="rgba(0, 29, 61, 0.5)" />
              <use href="#gentle-wave" x="48" y="5" fill="rgba(0, 29, 61, 0.3)" />
              <use href="#gentle-wave" x="48" y="7" fill="#001d3d" />
            </g>
          </svg>
        </div>

        <div className="footer-grid">
          <div>
            <h2 style={{color:'#f97316', margin:0}}>Antalya Diving</h2>
            <p style={{color:'#38bdf8', fontStyle:'italic', marginTop:'5px'}}>Akdeniz'in En İyi Dalış Noktalarını Keşfedin</p>
            <p style={{fontSize:'14px', opacity:0.8, lineHeight:'1.6', marginTop:'15px'}}>
              Antalya'nın gizli kalmış koylarını, antik kentlerini ve en lezzetli duraklarını keşfetmeniz için tasarlanan yapay zeka destekli rota asistanı.
            </p>
          </div>
          <div>
            <h3 style={{color:'#38bdf8', fontSize:'18px'}}>Hızlı Linkler</h3>
            <ul style={{listStyle:'none', padding:0, fontSize:'14px', opacity:0.8}}>
                <li style={{marginBottom:'10px'}}>• Popüler Rotalar</li>
                <li style={{marginBottom:'10px'}}>• Dalış Noktaları</li>
                <li style={{marginBottom:'10px'}}>• Hakkımızda</li>
                <li style={{marginBottom:'10px'}}>• Sıkça Sorulan Sorular</li>
            </ul>
          </div>
          <div>
            <h3 style={{color:'#38bdf8', fontSize:'18px'}}>İletişim</h3>
            <div style={{fontSize:'14px', opacity:0.8, lineHeight:'1.8'}}>
                <p>📍 Akdeniz Bulvarı No:123, Konyaaltı/Antalya</p>
                <p>📞 +90 532 123 45 67</p>
                <p>📧 info@antalyarota.com</p>
            </div>
          </div>
        </div>

        <div className="footer-stats-box">
          <div className="stat"><span className="number">14+</span><span className="label">Yıllık Deneyim</span></div>
          <div className="stat"><span className="number">15,000+</span><span className="label">Mutlu Gezgin</span></div>
          <div className="stat"><span className="number">50+</span><span className="label">Aktif Rota</span></div>
        </div>

        <div className="footer-bottom-bar">
          <p>© 2026 Antalya Rota Asistanı | <strong>Murat Çam</strong> - MAKÜ ZTYO Yönetim Bilişim Sistemleri</p>
          <p style={{marginTop:'10px', fontSize:'11px'}}>Made with ❤️ for Antalya</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
